CREATE TABLE IF NOT EXISTS resource_unit(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,resource_unit_code VARCHAR(64) NOT NULL,course_id BIGINT UNSIGNED NOT NULL,path_id BIGINT UNSIGNED NOT NULL,path_version_id BIGINT UNSIGNED NOT NULL,status VARCHAR(24) NOT NULL,aggregation_evidence_json JSON NOT NULL,correlation_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_resource_unit_code(resource_unit_code),KEY idx_resource_unit_path(path_version_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resource_unit_step(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,resource_unit_id BIGINT UNSIGNED NOT NULL,path_step_id BIGINT UNSIGNED NOT NULL,order_no INT NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_unit_step_version(path_step_id),UNIQUE KEY uk_unit_order(resource_unit_id,order_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resource_blueprint(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,blueprint_code VARCHAR(64) NOT NULL,resource_unit_id BIGINT UNSIGNED NOT NULL,profile_version_used BIGINT UNSIGNED NOT NULL,policy_version VARCHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,resource_plan_json JSON NOT NULL,learning_question_plan_json JSON NOT NULL,hidden_assessment_plan_json JSON NOT NULL,profile_evidence_json JSON NOT NULL,graph_evidence_json JSON NOT NULL,capability_snapshot_json JSON NOT NULL,schema_version VARCHAR(64) NOT NULL,correlation_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_blueprint_code(blueprint_code),KEY idx_blueprint_unit(resource_unit_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resource_generation_job(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,job_code VARCHAR(64) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,course_id BIGINT UNSIGNED NOT NULL,path_version_id BIGINT UNSIGNED NOT NULL,resource_unit_id BIGINT UNSIGNED NULL,blueprint_id BIGINT UNSIGNED NULL,generation_policy_version VARCHAR(64) NOT NULL,idempotency_key VARCHAR(128) NOT NULL,status VARCHAR(24) NOT NULL,retry_count INT NOT NULL DEFAULT 0,max_revision_rounds INT NOT NULL DEFAULT 5,input_snapshot_json JSON NULL,error_code VARCHAR(64) NULL,error_message VARCHAR(1000) NULL,correlation_id VARCHAR(64) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),started_at DATETIME(3) NULL,finished_at DATETIME(3) NULL,PRIMARY KEY(id),UNIQUE KEY uk_resource_job_code(job_code),UNIQUE KEY uk_resource_job_idempotency(user_id,idempotency_key),KEY idx_resource_job_status(status,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS course_resource_capability(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,course_id BIGINT UNSIGNED NOT NULL,resource_type VARCHAR(32) NOT NULL,enabled TINYINT NOT NULL DEFAULT 1,config_json JSON NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_course_resource_capability(course_id,resource_type)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resource_generation_policy(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,policy_version VARCHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,max_unit_knowledge_points INT NOT NULL DEFAULT 5,max_revision_rounds INT NOT NULL DEFAULT 5,question_similarity_threshold DECIMAL(6,4) NOT NULL DEFAULT 0.7200,config_json JSON NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(id),UNIQUE KEY uk_resource_policy(policy_version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
